type Service struct { inv Inventory; pricing Quoter; repo Repo }   // coarse boundary
func NewService(inv Inventory, p Quoter, r Repo) *Service { return &Service{inv, p, r} }
func (s *Service) PlaceOrder(ctx context.Context, req PlaceOrderRequest) (OrderID, error) {
	q, err := s.pricing.Quote(ctx, req.SKU, req.Qty)     // coarse-grained workflow
	if err != nil {
		return "", fmt.Errorf("place order: %w", err)
	}
	if err := s.inv.Reserve(ctx, req.SKU, req.Qty); err != nil {
		return "", err
	}
	return s.repo.Insert(ctx, req.CustomerID, q)         // tx owned by repo (pgx/sql.Tx)
}
